"""把字节数格式化成人类可读的样子。"""

UNITS = [("TB", 1024 ** 4), ("GB", 1024 ** 3), ("MB", 1024 ** 2), ("KB", 1024)]


def format_size(n):
    for unit, factor in UNITS:
        if n >= factor:
            return f"{n / factor:.1f} {unit}"
    return f"{n} B"
